<script setup lang="ts">import { Head, Link } from '@inertiajs/vue3'; import { Button } from '@/components/ui/button'; type Utility={id:string;type:string;type_label:string;billed_from:string;billed_to:string;paid_at:string;total_amount:number;business_percentage:string;household_percentage:string;business_amount:number;household_amount:number;physical_consumption:string|null;physical_consumption_unit:string|null;reference:string|null}; type Rate={id:string;type:string;type_label:string;suggested_rate:number|null;manual_rate:number|null;effective_rate:number;calculation_base_quantity:string;method:string;override_reason:string|null}; type Period={id:string;label:string;status_label:string;processed_flour_quantity:string;utilities:Utility[];rates:Rate[]}; defineProps<{period:Period}>(); const money=(value:number|null)=>value===null?'—':new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(value);</script><template><Head :title="`Costos ${period.label}`" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex justify-between gap-3"><div><p class="text-sm text-muted-foreground">Periodo de costos</p><h1 class="text-2xl font-semibold">{{ period.label }}</h1><p class="text-sm text-muted-foreground">{{ period.status_label }} · {{ period.processed_flour_quantity }} kg procesados</p></div><Button variant="outline" as-child><Link href="/cost-periods">Volver</Link></Button></header><section class="grid gap-4 lg:grid-cols-2"><article v-for="utility in period.utilities" :key="utility.id" class="rounded-xl border bg-card p-4"><h2 class="font-semibold">{{ utility.type_label }}</h2><p class="text-xs text-muted-foreground">{{ utility.billed_from }} a {{ utility.billed_to }} · pagada {{ utility.paid_at }}</p><div class="mt-4 grid grid-cols-3 gap-3 text-sm"><div><p class="text-xs text-muted-foreground">Total</p><strong>{{ money(utility.total_amount) }}</strong></div><div><p class="text-xs text-muted-foreground">Negocio {{ utility.business_percentage }} %</p><strong>{{ money(utility.business_amount) }}</strong></div><div><p class="text-xs text-muted-foreground">Hogar {{ utility.household_percentage }} %</p><strong>{{ money(utility.household_amount) }}</strong></div></div><p v-if="utility.physical_consumption" class="mt-3 text-xs">Consumo: {{ utility.physical_consumption }} {{ utility.physical_consumption_unit }}</p></article></section><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Costo</th><th class="px-4 py-3">Base anterior</th><th class="px-4 py-3">Sugerida</th><th class="px-4 py-3">Manual</th><th class="px-4 py-3">Efectiva</th><th class="px-4 py-3">Método</th></tr></thead><tbody class="divide-y"><tr v-for="rate in period.rates" :key="rate.id"><td class="px-4 py-3 font-medium">{{ rate.type_label }}</td><td class="px-4 py-3">{{ rate.calculation_base_quantity }} kg</td><td class="px-4 py-3">{{ money(rate.suggested_rate) }}</td><td class="px-4 py-3">{{ money(rate.manual_rate) }}</td><td class="px-4 py-3 font-semibold">{{ money(rate.effective_rate) }}/kg</td><td class="px-4 py-3">{{ rate.method==='manual'?'Manual':'Sugerida' }}</td></tr></tbody></table></section></main></template>
